#[path="base.rs"]mod base;
use base::*;use zopro_bn254::Fr;use serde_json::json;
fn main(){let n=32768;let qs=choose_primes(n);let context=Context::new(n,&qs);let(a,da)=polynomial_values(&[Fr::from(37u64),-Fr::ONE,Fr::from(7u64)],n);let(b,db)=polynomial_values(&[-Fr::from(13u64),Fr::from(11u64),Fr::ONE,Fr::from(29u64)],n);let got=context.product_direct_reference(&a,&b);let expected=(0..n).map(|i|(da[i]*b[i]+a[i]*db[i])*Fr::from(n as u64)).collect::<Vec<_>>();assert_eq!(got,expected);let out=json!({"complete":true,"domain":n,"coordinates_checked":n,"prime_count":qs.len(),"projection":"integer fixed coefficients, exact wrapped lowword residual","CRT":"integer fixed32 correction and scalar Fr dot product","input_lift":"one rawMontgomery operand; inverseR output compensation","native_SIMD_helpers_implemented":false,"new_latency_claim":false,"new_proofs":0,"proof_ledger":29953,"production_changed":false,"adopted":false,"goal_achieved":false});std::fs::write("/home/ubuntu/src/zopro-perf-work/crt-euler-direct176/algebra-direct.json",serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{out}");}
